{
  "status": "SUPPORTED",
  "task_summary": "Arrange refreshment settings for two people and position an entertainment control for shared access.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "person",
        "entity_kind": "OBJECT",
        "function": "The beneficiary of the arrangement, determining the number of settings and accessibility requirements.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["human"],
        "required_properties": []
      },
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A set of items (plate, cup) for consuming refreshments.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["plate", "cup", "snack_set"],
        "required_properties": ["holds_food_or_drink"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote_control"],
        "required_properties": ["operates_television"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "A flat, stable area to hold items.",
        "required_count": 3,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "console_table", "coffee_table"],
        "required_properties": ["is_flat", "supports_weight"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "The display screen being watched.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv_screen"],
        "required_properties": ["display_content"]
      }
    ],
    "functional_relations": [
      {
        "id": "setting_proximity",
        "relation": "near",
        "participant_roles": ["refreshment_setting", "person"],
        "required": true
      },
      {
        "id": "accessibility",
        "relation": "accessible_to",
        "participant_roles": ["entertainment_control", "person"],
        "required": true
      },
      {
        "id": "support_location",
        "relation": "on",
        "participant_roles": ["refreshment_setting", "surface"],
        "required": true
      },
      {
        "id": "control_location",
        "relation": "on",
        "participant_roles": ["entertainment_control", "surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_settings",
        "operation": "place_refreshment_setting",
        "participant_roles": ["refreshment_setting", "surface", "person"],
        "operation_count": 2
      },
      {
        "id": "position_control",
        "operation": "place_entertainment_control",
        "participant_roles": ["entertainment_control", "surface", "person"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "person": [],
      "refreshment_setting": [
        {
          "label": "Plate and cup set",
          "visual_description": "Two white plates and two red cups sitting on the large wooden desk on the right."
        }
      ],
      "entertainment_control": [
        {
          "label": "Remote control",
          "visual_description": "A black remote control resting on the same desk as the plates."
        }
      ],
      "surface": [
        {
          "label": "Large desk",
          "visual_description": "Wooden desk on the right with drawers, currently holding refreshments and remote."
        },
        {
          "label": "Coffee table",
          "visual_description": "Rectangular glass-topped table in the center of the seating area."
        },
        {
          "label": "Side table",
          "visual_description": "Small wooden table beneath the wall-mounted television."
        }
      ],
      "television": [
        {
          "label": "Wall-mounted screen",
          "visual_description": "Black rectangular screen mounted high on the left wall."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk_drawers",
        "label": "Desk drawers",
        "visual_description": "The large wooden desk has front-facing panels suggesting drawers or cabinet doors.",
        "reason": "Could contain additional plates, cups, or remotes needed to fulfill the task."
      },
      {
        "id": "side_table_storage",
        "label": "Side table storage",
        "visual_description": "The table under the TV appears to have a lower section or shelf.",
        "reason": "Could be used to store or retrieve items if the main surfaces are insufficient."
      }
    ],
    "inspection_order": [
      "desk_drawers",
      "side_table_storage"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
